272	// Drain CPU state into `*s`. pc is computed by the caller (from a
273	// HandoffSite for trigger paths). If minstret_override is non-zero, it
274	// replaces QEMU's PMU minstret.
275	static void drain_state_into(unsigned int vcpu_idx, uint64_t pc,
276	                             uint64_t minstret_override,
277	                             struct hybrid_state_v1 *sp)
278	{
279	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
280	    resolve_handles(v);
281	    memset(sp, 0, sizeof(*sp));
282	    struct hybrid_state_v1 s = {0};
283	    s.magic   = HYBRID_STATE_MAGIC;
284	    s.version = HYBRID_STATE_VERSION;
285	    s.flags   = HYBRID_FLAG_RV64;
286	    s.hart_id = vcpu_idx;
287	    // L6: real privilege at the boundary; M-mode fallback only when the
288	    // stub doesn't advertise the gdbstub virtual feature (a missing handle
289	    // reads as 0 = U, which would silently demote the hart).
290	    s.priv    = v->priv ? (read_reg64(v->priv) & 0x3) : 3;
291	    s.pc      = pc;
292	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
293	
294	    // Floating-point: only set FP flag if at least one handle was bound,
295	    // i.e. QEMU advertised the FPU feature (D extension).
296	    int has_fp = 0;
297	    for (int i = 0; i < 32; i++) {
298	        s.fpr[i] = read_reg64(v->fpr[i]);
299	        if (v->fpr[i]) has_fp = 1;
300	    }
301	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
302	    s.fcsr = read_reg64(v->fcsr);  // L20: rides HYBRID_FLAG_FP
303	
304	    s.mstatus  = read_reg64(v->mstatus);
305	    s.mepc     = read_reg64(v->mepc);
306	    s.mtvec    = read_reg64(v->mtvec);
307	    s.mcause   = read_reg64(v->mcause);
308	    s.mtval    = read_reg64(v->mtval);
309	    s.mscratch = read_reg64(v->mscratch);
310	    s.medeleg  = read_reg64(v->medeleg);
311	    s.mideleg  = read_reg64(v->mideleg);
312	    s.mip      = read_reg64(v->mip);
313	    s.mie      = read_reg64(v->mie);
314	    s.mcycle   = read_reg64(v->mcycle);
315	    s.minstret = minstret_override ? minstret_override
316	                                   : read_reg64(v->minstret);
317	    s.satp     = read_reg64(v->satp);
318	
319	    // Andes cache fix: carry crt0's cache-enable so the cycle engine resumes
320	    // with caches on (NULL handle on a non-Andes stub reads back as 0).
321	    s.mcache_ctl = read_reg64(v->mcache_ctl);
322	    s.mmisc_ctl  = read_reg64(v->mmisc_ctl);
323	
324	    // Andes V5 CSR block (v3): drain every transported Andes CSR. Set
325	    // HYBRID_FLAG_ANDES if the stub advertised at least one (mirrors has_fp/
326	    // has_v); otherwise the block stays zero and consumers skip it. A NULL
327	    // handle on a non-Andes stub reads back as 0 -> tolerant.
328	    int has_andes = 0;
329	#define HYBRID_ANDES_FIELD(field, addr, name)  \
330	    s.andes.field = read_reg64(v->andes_##field); \
331	    if (v->andes_##field) has_andes = 1;
332	    HYBRID_ANDES_CSR_LIST(HYBRID_ANDES_FIELD)
333	#undef HYBRID_ANDES_FIELD
334	    for (int i = 0; i < HYBRID_PMA_CFG_NUM; i++) {
335	        s.andes.pmacfg[i] = read_reg64(v->pmacfg[i]);
336	        if (v->pmacfg[i]) has_andes = 1;
337	    }
338	    for (int i = 0; i < HYBRID_PMA_ADDR_NUM; i++) {
339	        s.andes.pmaaddr[i] = read_reg64(v->pmaaddr[i]);
340	        if (v->pmaaddr[i]) has_andes = 1;
341	    }
342	    if (has_andes) s.flags |= HYBRID_FLAG_ANDES;
343	
344	    // M-ext CSR block (v4): drain every transported M-mode CSR the stub
345	    // advertised. Set HYBRID_FLAG_M_EXT if at least one resolved; a NULL handle
346	    // reads 0. The vsim caps gate decides which of these the cycle engine
347	    // actually restores, so draining an absent-on-vsim CSR here is harmless.
348	    int has_m_ext = 0;
349	#define HYBRID_M_EXT_FIELD(field, addr, name)  \
350	    s.m_ext.field = read_reg64(v->m_ext_##field); \
351	    if (v->m_ext_##field) has_m_ext = 1;
352	    HYBRID_M_EXT_CSR_LIST(HYBRID_M_EXT_FIELD)
353	#undef HYBRID_M_EXT_FIELD
354	    if (has_m_ext) s.flags |= HYBRID_FLAG_M_EXT;
355	
356	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
357	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
358	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
359	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
360	
361	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
362	    // bounds the per-register byte count copied into vreg[]. The policy
363	    // helper (hybrid_v_drain_policy) decides SKIP/OK/ABORT from the
364	    // handle truthiness so we don't conflate "stub missing vlenb" with
365	    // "V disabled at runtime"; see include/hybrid/v_drain_policy.h.
366	    s.vstart = read_reg64(v->vstart);
367	    s.vxsat  = read_reg64(v->vxsat);
368	    s.vxrm   = read_reg64(v->vxrm);
369	    s.vcsr   = read_reg64(v->vcsr);
370	    s.vtype  = read_reg64(v->vtype);
371	    s.vl     = read_reg64(v->vl);
372	    s.vlenb  = read_reg64(v->vlenb);
373	    int has_other_v = (v->vstart || v->vxsat || v->vxrm || v->vcsr
374	                       || v->vtype || v->vl);
375	    if (!has_other_v) {
376	        for (int i = 0; i < 32; i++)
377	            if (v->vreg[i]) { has_other_v = 1; break; }
378	    }
379	    HybridVDrainPolicy vpol = hybrid_v_drain_policy(
380	        v->vlenb != NULL, has_other_v, s.vlenb);
381	    if (vpol == HYBRID_V_DRAIN_ABORT) {
382	        if (v->vlenb == NULL)
383	            fprintf(stderr,
384	                    "hybrid_handoff: stub advertised V CSRs/regs but not "
385	                    "vlenb; refusing to drain partial V state\n");
386	        else
387	            fprintf(stderr,
388	                    "hybrid_handoff: vlenb=%" PRIu64 " exceeds the wire-format "
389	                    "ceiling HYBRID_VLEN_BYTES_MAX=%d (VLEN %d); refusing to "
390	                    "truncate V registers\n",
391	                    s.vlenb, HYBRID_VLEN_BYTES_MAX,
392	                    8 * HYBRID_VLEN_BYTES_MAX);
393	        exit(2);
394	    }
395	    if (vpol == HYBRID_V_DRAIN_OK) {
396	        s.flags |= HYBRID_FLAG_V;
397	        /* The policy guarantees vlenb <= HYBRID_VLEN_BYTES_MAX here, so the
398	         * full live register fits the wire-format slot -- no clamp (L11). */
399	        for (int i = 0; i < 32; i++)
400	            (void) read_reg_bytes(v->vreg[i],
401	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
402	                                  (size_t) s.vlenb);
403	    }
404	
405	    *sp = s;
406	}
407	
408	// Drain CPU state to `path`. Does NOT call exit -- the caller decides
409	// exit(200).
410	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
411	                                uint64_t minstret_override, const char *path)
412	{
413	    struct hybrid_state_v1 s;
414	    drain_state_into(vcpu_idx, pc, minstret_override, &s);

