auto capture_reset_baseline(
  hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
                        PLATFORM::dmi_data_width>& bus,
  const hybrid_state_v1& input) -> hybrid_state_v1
{
  hybrid::StateDrain drain(bus, v_scratch_gpa(),
                           hybrid::andes_caps_from_config());
  drain.set_gpr_block_store(true);
  drain.set_fpr_block_store(true);
  drain.set_csr_sweep(true);
  // At reset mstatus.FS/VS are Off, so the capture's fsd/vse8 sweeps (and
  // the FPR/V CSR abstract reads) would raise illegal instruction
  // (cmderr=3). Halt and enable them first, exactly like resume() does
  // before its FPR/V writes. Safe to clobber: mstatus is never re-read by
  // a drain nor gated by the baseline, and resume() rewrites it whenever
  // the FP/V flags are set -- the only case this branch runs.
  if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
    using RD = hybrid::ResumeDriver;
    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
    bus.write(RD::kDmcontrol,
              RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
    hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
                           "reset-baseline capture halt");
    const uint64_t mstatus = hybrid::read_register_64(
      bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
    uint64_t enable = mstatus;
    if ((input.flags & HYBRID_FLAG_FP)
        && (enable & RD::kMstatusFsMask) == 0)
      enable |= RD::kMstatusFsInitial;
    if ((input.flags & HYBRID_FLAG_V)
        && (enable & RD::kMstatusVsMask) == 0)
      enable |= RD::kMstatusVsInitial;
    if (enable != mstatus)
      hybrid::write_register_abstract(
        bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
  }
  hybrid_state_v1 probe{};
  probe.magic = HYBRID_STATE_MAGIC;
  probe.version = HYBRID_STATE_VERSION;
  probe.flags = input.flags;
  probe.vlenb = input.vlenb;
  auto baseline = drain.drain_with_passthrough(probe);
  lift_scratch_blocks(baseline, /*csr_swept=*/true);
  return baseline;
}

