215	    std::optional<hybrid_state_v1> baseline{};
216	    bool baseline_captured = false;
217	    if (!baseline_cache.empty()) {
218	      baseline = hybrid::try_load_reset_baseline(baseline_cache);
219	      // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
220	      // incoming state was captured under a different engine/QEMU pairing.
221	      if (baseline
222	          && ((baseline->flags & hybrid_input_state_->flags)
223	                != hybrid_input_state_->flags
224	              || baseline->vlenb != hybrid_input_state_->vlenb))
225	        baseline.reset();
226	      if (!baseline) {
227	        baseline = capture_reset_baseline(bus, *hybrid_input_state_);
228	        baseline_captured = true;
229	        if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
230	          spdlog::warn("hybrid: cannot save reset baseline to {}",
231	                       baseline_cache);
232	      }
233	      spdlog::info("hybrid: reset baseline {} ({})",
234	                   baseline_captured
235	                     ? "captured -- one-time cost per engine build + ELF"
236	                     : "cache hit",
237	                   baseline_cache);
238	    }
239	
240	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
241	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
242	    // this region to repopulate v0..v31, so the bytes must be in place first.
243	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
244	    // dropping V state.
245	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
246	      hybrid::stage_v_to_scratch(*hybrid_input_state_,
247	                                 platform.main_memory.data);
248	    }
249	    // GPR block-load: stage x1..x31 into the scratch page so the resume
250	    // ld-sweep repopulates them in ~6 DM round-trips instead of 31 abstract
251	    // writes. Host memcpy is free. Gate on gpr_scratch_fits -- the same
252	    // condition ResumeDriver uses -- so when the V data fills the page we skip
253	    // staging (the abstract-write fallback runs) and never clobber v30/v31.
254	    if (hybrid::gpr_scratch_fits(hybrid_input_state_->vlenb))
255	      hybrid::stage_gpr_to_scratch(*hybrid_input_state_,
256	                                   platform.main_memory.data);
257	    // FPR block-load: stage f0..f31 just below the GPR block so the resume
258	    // fld-sweep repopulates them in ~6 DM round-trips instead of 32 abstract
259	    // writes. Gate on the FP flag and fpr_scratch_fits (tighter than the GPR
260	    // gate -- the FPR block sits lower in the page), so a full V page skips
261	    // staging and the abstract-write fallback runs.
262	    if ((hybrid_input_state_->flags & HYBRID_FLAG_FP) != 0u
263	        && hybrid::fpr_scratch_fits(hybrid_input_state_->vlenb))
264	      hybrid::stage_fpr_to_scratch(*hybrid_input_state_,
265	                                   platform.main_memory.data);
