275	    driver.set_gpr_block_load(true);
276	    driver.set_fpr_block_load(true);
277	    // LG3: on a capture run the capture drain's V dump sweep clobbered
278	    // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
279	    if (baseline)
280	      driver.set_reset_baseline(*baseline,
281	                                /*v_cfg_at_reset=*/!baseline_captured);
282	    driver.resume(*hybrid_input_state_);
283	    if (baseline)
284	      spdlog::info("hybrid: liveness gate elided {} register restores",
285	                   driver.baseline_skip_count());
